function OpenPopup () {

    const mainWrap = document.getElementById( 'wpwrap' );

    let _addPopup = () => {

        var item = document.createElement('div');
        item.className = 'popup';
        item.innerHTML = `<form><input type="text"><button>Submit</button></form>`;

        mainWrap.appendChild( item );

        let form = item.querySelector( 'form' );

        form.addEventListener( 'submit', (e) => {
            e.preventDefault();
            _sendRequest();
        } )

    };

    let _sendRequest = () => {

        let formData = new FormData();

        formData.append( 'action', 'get_instagram_data' );

        let xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function() {
            if (xhr.readyState == XMLHttpRequest.DONE) {
                console.log(xhr.response)
            }
        };
        xhr.open('POST', ajaxurl, true);
        xhr.send( formData );

    };

    btn.addEventListener( 'click', _addPopup )

}

function SetInstaGraberForm () {

    instaGraberForm.addEventListener( 'submit', () => {
        instaGraberForm.classList.add( 'is-loading' );
    } )

}

function Preloader() {

    let _constructPage = () => {

        // btn = document.querySelector('#instagram-importer');
        instaGraberForm = document.getElementById( 'insta-graber__form' );

        if ( btn ){
            new OpenPopup();
        }

        if ( instaGraberForm ){
            new SetInstaGraberForm();
        }

    }

    window.addEventListener( 'load', _constructPage )

}
